/// <summary>
/// Story dialog lines (cinderreach-deutsch-story S5/S6). German is the original,
/// English a faithful fallback. Line keys follow <see cref="StoryDialog.Key"/>;
/// voices and facts follow docs/story-bible.md.
/// </summary>
public static partial class LocCatalog
{
    static readonly Entry[] Dialog =
    {
        // ---- H1 Die dunkle Tür ----
        E("dlg.h1.offer.1", "Siebenundvierzig Laternen. Gestern waren es achtundvierzig. Die dunkle hängt über der Tür von Witwe Rösch. Sie hat es noch nicht gemerkt, sie schläft.", "Forty-seven lanterns. Yesterday there were forty-eight. The dark one hangs over widow Rösch's door. She hasn't noticed yet, she's asleep."),
        E("dlg.h1.offer.2", "Seit vierzig Tagen kommt kein Karren aus dem Beinhaus. Ohne Tote brennt der Ofen nicht. Ohne Ofen kein Glas. Ohne Glas …", "No cart has come from the ossuary in forty days. Without the dead the kiln doesn't burn. Without the kiln, no glass. Without glass …"),
        E("dlg.h1.offer.3", "Der letzte Karren steckt im Moor, bei der alten Kiste. Ein Moorschläger hat sich dort eingenistet.", "The last cart is stuck in the fen, by the old chest. A fen brute has settled in there."),
        E("dlg.h1.offer.4", "An jedem Karren hängt ein Fuhrbrief. Bringt ihn mir. Ich will wissen, wen sie geladen hatten.", "Every cart carries a cart letter. Bring it to me. I want to know who they had loaded."),
        E("dlg.h1.hint.1", "Der Fuhrbrief hängt am Karren, bei der Kiste im Moor. Und der Moorschläger wird nicht vergessen, dass ihr da wart.", "The cart letter hangs on the cart, by the chest in the fen. And the brute won't forget you were there."),
        E("dlg.h1.done.1", "Zeigt her.", "Show me."),
        E("dlg.h1.done.2", "Ottilie liest. Dann dreht sie den Brief um, als stünde auf der Rückseite etwas anderes.", "Ottilie reads. Then she turns the letter over, as if the back might say something else."),
        E("dlg.h1.done.3", "Zwölf Namen. Gestempelt, gezählt, verladen. Und der Karren war leer, sagt ihr?", "Twelve names. Stamped, counted, loaded. And the cart was empty, you say?"),
        E("dlg.h1.done.4", "Dann ist er nie beladen worden, und jemand hat trotzdem unterschrieben.", "Then it was never loaded, and someone signed for it anyway."),
        E("dlg.h1.done.5", "Das Siegel ist vom Abt. Ich war Novizin bei ihm, elf Jahre lang. Ich hätte nie gedacht, dass er lügt.", "The seal is the abbot's. I was his novice for eleven years. I never thought he would lie."),

        // ---- H2 Die Siegel vom Stillen Grund ----
        E("dlg.h2.offer.1", "Das Versunkene Beinhaus liegt hinter dem Moortor. Die Brüder vom Stillen Grund waschen dort die Toten, schreiben sie ein und geben sie dem Ofen. Seit vierzig Tagen geben sie nichts mehr.", "The Sunken Ossuary lies beyond the Fen Gate. The Brothers of the Still Ground wash the dead there, enter their names and give them to the kiln. For forty days they have given nothing."),
        E("dlg.h2.offer.2", "Man sagt, der Abt habe die Gebeine seiner Brüder aufstehen lassen. Wer nachsehen wollte, kam nicht zurück.", "They say the abbot made his brothers' bones stand up. Whoever went to look did not come back."),
        E("dlg.h2.offer.3", "Geht hinunter. Findet heraus, was er hütet. Und wenn er euch nicht durchlässt …", "Go down. Find out what he guards. And if he won't let you through …"),
        E("dlg.h2.offer.4", "… dann tut, wofür die Wacht euch bezahlt. Ich bete für ihn. Das kostet nichts.", "… then do what the Hold pays you for. I'll pray for him. That costs nothing."),
        E("dlg.h2.offer.5", "Das Band am zweiten Karren trug das Siegel des Vogts. Er wusste also davon. Er hat nur nichts gesagt.", "The ribbon on the second cart bore the reeve's seal. So he knew about it. He just said nothing."),
        E("dlg.h2.hint.1", "Hinter dem Moortor. Die Knochenwächter tragen noch die Kutten der Brüder. Erschlagt sie trotzdem.", "Beyond the Fen Gate. The bone wardens still wear the brothers' habits. Strike them down anyway."),
        E("dlg.h2.done.1", "Ihr riecht nach Kalk und Weihrauch. Er ist tot?", "You smell of lime and incense. He's dead?"),
        E("dlg.h2.done.2", "Gebt mir, was er bei sich trug. Nicht hier. Kommt wieder, wenn ich es gelesen habe.", "Give me what he carried. Not here. Come back when I've read it."),

        // ---- H3 Lest die Namen (Wendung 1) ----
        E("dlg.h3.offer.1", "Ottilie hat das Brevier des Abts auf den Knien. Neben ihr brennt keine Kerze.", "Ottilie holds the abbot's breviary on her knees. No candle burns beside her."),
        E("dlg.h3.offer.2", "Er hat nicht gehortet. Er hat gezählt. Hier, die Fuhrlisten des Ofens: Jeden Monat mehr Namen, als im ganzen Moor gestorben sind.", "He wasn't hoarding. He was counting. Here, the kiln's cart lists: every month more names than died in the whole fen."),
        E("dlg.h3.offer.3", "Hinter manchen Namen steht kein Todestag. Hinter einem steht ‚hustet noch‘.", "Some names have no date of death. One says ‘still coughing’."),
        E("dlg.h3.offer.4", "Er hat aufgehört, Tote herauszugeben, weil der Ofen Lebende bestellt hat. Und ihr habt ihn dafür …", "He stopped giving up the dead because the kiln was ordering the living. And you killed him for …"),
        E("dlg.h3.offer.5", "Nein. Ich habe euch geschickt.", "No. I sent you."),
        E("dlg.h3.offer.6", "Thewes stand auf einer der Tafeln. Er hat dem Abt seine Knochen gegeben, damit der Grund gehütet bleibt. Und ich habe euch hinterhergeschickt.", "Thewes was on one of the tablets. He gave the abbot his bones so the ground would stay guarded. And I sent you after them."),
        E("dlg.h3.offer.7", "Jorin Hagedorn war Lehrling am Ofen. Redet mit ihm, bevor ihr hingeht. Er sagt nicht viel, aber er lügt nicht.", "Jorin Hagedorn was an apprentice at the kiln. Talk to him before you go. He doesn't say much, but he doesn't lie."),
        E("dlg.h3.offer.8", "Thewes' Licht habt ihr gefunden. Seinen Namen habe ich selbst auf die Liste gesetzt. Vergebt mir, oder lasst es.", "You found Thewes' light. I put his name on the list myself. Forgive me, or don't."),
        E("dlg.h3.hint.1", "Redet mit Jorin an der Schmiede. Dann in den Glutofen. Der Weg führt durch das Beinhaus.", "Talk to Jorin at the smithy. Then into the Cinder Kiln. The way leads through the ossuary."),
        E("dlg.h3.talk.jorin.1", "Ottilie schickt euch. Hab's mir gedacht.", "Ottilie sent you. Figured."),
        E("dlg.h3.talk.jorin.2", "Die Meisterin. Ihr nennt sie Ofenmutter. Wir haben sie nie so genannt, wenn sie zugehört hat.", "The master. You call her the Kilnmother. We never called her that when she could hear."),
        E("dlg.h3.talk.jorin.3", "Ich hab die Lanzen ihrer Wächter geschmiedet. Gegen Plünderer, hieß es. Gegen Plünderer braucht man keine Widerhaken.", "I forged her wardens' lances. Against looters, they said. You don't need barbs against looters."),
        E("dlg.h3.talk.jorin.4", "Ihre Knechte glühen. Nicht von der Arbeit. Wenn sie fallen, platzen sie. Bleibt nicht stehen, wenn einer fällt.", "Her thralls glow. Not from the work. When they fall, they burst. Don't stand still when one falls."),
        E("dlg.h3.talk.jorin.5", "Und sie wird euch vorrechnen, wie viele Laternen noch brennen. Sie hat immer richtig gerechnet. Das war das Schlimme.", "And she'll do the sums for you, how many lanterns still burn. Her sums were always right. That was the worst of it."),

        // ---- H4 Asche schuldet niemand ----
        E("dlg.h4.hint.1", "Der Ofen brennt noch. Solange er brennt, hört sie nicht auf.", "The kiln still burns. As long as it burns, she won't stop."),
        E("dlg.h4.done.1", "Das ist ihr Brennbuch? Schwer. Ruß an jeder Seite.", "That's her firing book? Heavy. Soot on every page."),
        E("dlg.h4.done.2", "Sie hat euch etwas gesagt, bevor sie fiel. Ich seh es euch an. Nein, sagt es mir nicht. Ich lese es selbst.", "She said something to you before she fell. I can see it on you. No, don't tell me. I'll read it myself."),
        E("dlg.h4.done.3", "Jorin hat heute sechs Spitzen eingeschmolzen. Er sagt, das sei seit Jahren das erste Stück, das er gern macht.", "Jorin melted down six points today. He says it's the first piece in years he's been glad to make."),
        E("dlg.h4.done.4", "Gebt mir einen Abend damit.", "Give me an evening with it."),

        // ---- H5 Siebenundvierzig (Wendung 2) ----
        E("dlg.h5.offer.1", "Ottilie steht vor der Laterne über Ilsabes Tür. Das Rußbuch liegt aufgeschlagen auf der Schwelle.", "Ottilie stands under the lantern above Ilsabe's door. The soot book lies open on the threshold."),
        E("dlg.h5.offer.2", "Spenden. So heißt das hier. ‚Spende Krumm, zwei Personen, Ausgleich in Glas.‘", "Donations. That's the word here. ‘Donation Krumm, two persons, settled in glass.’"),
        E("dlg.h5.offer.3", "Der alte Feddersen, der nicht mehr laufen konnte. Die Kinder vom Hirten, nach dem Fieber. Alle hier drin. Jeder mit einem Preis.", "Old Feddersen, who couldn't walk any more. The shepherd's children, after the fever. All in here. Each with a price."),
        E("dlg.h5.offer.4", "Und unten auf jeder Seite das Siegel des Vogts.", "And at the foot of every page, the reeve's seal."),
        E("dlg.h5.offer.5", "Ihr kennt die Handschrift, nicht wahr? Aus ihrem Lieferbuch. Ihr habt nichts gesagt.", "You know the handwriting, don't you? From her ledger. You said nothing."),
        E("dlg.h5.offer.6", "Geht zu ihr. Sie soll es euch selbst sagen. Mir würde sie nur erklären, warum es nötig war.", "Go to her. Let her tell you herself. To me she'd only explain why it was necessary."),
        E("dlg.h5.hint.1", "Ilsabe ist an ihrem Stand. Sie ist immer an ihrem Stand.", "Ilsabe is at her stall. She's always at her stall."),
        E("dlg.h5.talk.ilsabe.1", "Ah. Ihr habt das Buch. Dann sparen wir uns das Vorspiel.", "Ah. You have the book. Then let's skip the preamble."),
        E("dlg.h5.talk.ilsabe.2", "Ja, ich habe vermittelt. Leute, die niemanden mehr hatten. Die den Winter nicht überstanden hätten. Die Wacht hätte ihn ohne Licht auch nicht überstanden.", "Yes, I arranged it. People who had no one left. Who wouldn't have survived the winter. The Hold wouldn't have survived it without light either."),
        E("dlg.h5.talk.ilsabe.3", "Der Vogt hat gesiegelt, ich habe gerechnet, die Meisterin hat gebrannt. Und ihr habt jede Nacht unter einer Laterne geschlafen. Sagt mir, wer von uns das nicht wusste.", "The reeve sealed, I counted, the master burned. And you slept under a lantern every night. Tell me which of us didn't know."),
        E("dlg.h5.talk.ilsabe.4", "Ich verkaufe nichts, was nicht vorher jemand hergegeben hat. Das ist der ganze Handel. Wollt ihr trotzdem etwas kaufen?", "I sell nothing that someone didn't give up first. That's the whole trade. Do you still want to buy something?"),
        E("dlg.h5.done.1", "Sie hat es zugegeben. Natürlich. Sie schämt sich nicht, sie rechnet.", "She admitted it. Of course she did. She isn't ashamed, she counts."),
        E("dlg.h5.done.2", "Ottilie nimmt die Kappe von der Laterne über Ilsabes Tür und drückt den Docht mit zwei Fingern aus. Es zischt nicht. Glutglas zischt nicht.", "Ottilie lifts the cap off the lantern over Ilsabe's door and pinches the wick out with two fingers. It doesn't hiss. Emberglass doesn't hiss."),
        E("dlg.h5.done.3", "Sechsundvierzig.", "Forty-six."),
        E("dlg.h5.done.4", "Morgen werden sie mich fragen, warum es dunkel ist. Ich werde es ihnen sagen. Und dann werden sie fragen, wann wieder Glas kommt.", "Tomorrow they'll ask me why it's dark. I'll tell them. And then they'll ask when the glass comes back."),

        // ---- H6–H9 Was im Glas wohnt (Wendung 3) ----
        E("dlg.h6.offer.1", "Ein Karren steht am Moortor, leer bis auf einen Sack. Die Frau auf dem Bock hat Glasstaub in den Wimpern.", "A cart stands at the Fen Gate, empty but for one sack. The woman on the box has glass dust in her lashes."),
        E("dlg.h6.offer.2", "Merle Sandkamp. Ich fahre Asche, vom Ofen in die Brache. Fuhr. Der Ofen ist kalt. Wart ihr das?", "Merle Sandkamp. I haul ash, from the kiln to the barrens. Hauled. The kiln is cold. Was that you?"),
        E("dlg.h6.offer.3", "Gut. Dann wisst ihr schon das meiste. Den Rest wisst ihr nicht.", "Good. Then you know most of it. You don't know the rest."),
        E("dlg.h6.offer.4", "Der Glasmacher sitzt in der Glasbrache und schmilzt, was wir bringen. Er hat nie gefragt, was in den Säcken war. Ich habe nie gefragt, warum er nicht fragt.", "The Glasswright sits in the Glass Barrens and melts what we bring. He never asked what was in the sacks. I never asked why he didn't ask."),
        E("dlg.h6.offer.5", "In der Brache wächst einem das Glas auf der Brust, wenn man zu lange in eine Richtung schaut. Mein Bruder Tamm hat immer nach Hause geschaut. Er ist noch dort.", "In the barrens, glass grows on your chest if you look one way too long. My brother Tamm always looked toward home. He's still out there."),
        E("dlg.h6.offer.6", "Geht hin. Ich komme nicht mit. Ich habe meinen Teil gefahren.", "Go. I'm not coming. I've driven my share."),
        E("dlg.h6.hint.1", "Die Brache liegt hinter dem Ofen, durch das Tor südlich der Kuppeln.", "The barrens lie past the kiln, through the gate south of the domes."),
        E("dlg.h7.hint.1", "Die Seher lesen in Scherben. Nehmt ihnen die Gläser ab und schaut selbst hinein. Mir haben sie nie gezeigt, was ich sehen wollte.", "The augurs read shards. Take their glasses and look for yourselves. They never showed me what I wanted to see."),
        E("dlg.h8.hint.1", "Er sitzt in der Mitte, wo das Glas am dicksten ist. Er wird reden. Lasst ihn reden, er hatte lange niemanden.", "He sits in the middle, where the glass is thickest. He'll talk. Let him, he's had no one for a long time."),
        E("dlg.h9.talk.merle.1", "Ihr habt das Prisma. Es ist warm, nicht wahr? Er hat gesagt, das sei seine Frau. Wendeline.", "You have the prism. It's warm, isn't it? He said that was his wife. Wendeline."),
        E("dlg.h9.talk.merle.2", "Die Sehgläser haben euch die Wacht gezeigt. Von außen. Die Hüllen im Nebel, alle mit dem Gesicht zum Licht.", "The seeing glasses showed you the Hold. From outside. The husks in the fog, all facing the light."),
        E("dlg.h9.talk.merle.3", "Sie kommen nicht trotz der Laternen. Sie kommen, weil ihre Glut darin steckt. Sie wollen nach Hause.", "They don't come despite the lanterns. They come because their ember is inside them. They want to go home."),
        E("dlg.h9.talk.merle.4", "Ich verkaufe das Glas nicht mehr. Tamm liegt jetzt mit drin.", "I don't sell the glass any more. Tamm is in there now too."),
        E("dlg.h9.talk.merle.5", "Den Sack verkaufe ich trotzdem. Irgendwer kauft immer Licht, und ich muss essen.", "I'll sell the sack anyway. Someone always buys light, and I have to eat."),
        E("dlg.h9.talk.merle.6", "Sagt Ottilie, was ihr gesehen habt. Sie ist die Einzige, die die Laternen zählt.", "Tell Ottilie what you saw. She's the only one who counts the lanterns."),
        E("dlg.h9.talk.ottilie.1", "Ottilie hält eine Scherbe gegen ihre Laterne. Das Licht darin flackert im Takt eines Atems.", "Ottilie holds a shard against her lantern. The light inside flickers like breathing."),
        E("dlg.h9.talk.ottilie.2", "Sechsundvierzig. Und jede ist jemand.", "Forty-six. And every one is someone."),
        E("dlg.h9.talk.ottilie.3", "Wenn wir sie zerschlagen, ist es dunkel. Wenn nicht, kommen sie weiter. Sie wollen nur nach Hause.", "If we smash them, it's dark. If we don't, they keep coming. They only want to go home."),
        E("dlg.h9.talk.ottilie.4", "Und Ilsabe kauft schon Sehgläser, damit sie weiß, wann sie kommen. Sie wird ihnen etwas anbieten. Jemanden.", "And Ilsabe is already buying seeing glasses, so she knows when they come. She'll offer them something. Someone."),
        E("dlg.h9.talk.ottilie.5", "Hinter dem Moortor stehen Hüllen im Nebel und sehen herüber. Keine kommt näher. Noch nicht.", "Beyond the Fen Gate, husks stand in the fog and look across. None comes closer. Not yet."),
        E("dlg.h9.talk.ottilie.6", "Geht schlafen. Ich zähle noch einmal.", "Go and sleep. I'll count once more."),
        // Akt II Vertiefung S2: H9-Folgen (N12 → Merle vergräbt, N13/N15 → Ottilie liest mit).
        E("dlg.h9.talk.merle.7", "Tamms Rad habe ich vergraben, mit dem Glas obendrauf. Verkauft wird hier nichts mehr.", "I buried Tamm's wheel, with the glass on top. Nothing gets sold here any more."),
        E("dlg.h9.talk.ottilie.7", "Fünf Gläser hat sie jetzt. Ilsabe liest darin die Nächte der Hüllen — und wir zählen mit.", "She has five glasses now. Ilsabe reads the husks' nights in them — and we count along."),
        E("dlg.h9.talk.ottilie.8", "Eine Spendenseite pro Laterne. Irgendwer zahlt immer — sorgt dafür, dass ihr es nicht seid.", "One donation page per lantern. Someone always pays — make sure it isn't you."),

        // ---- Akt II Vertiefung S2: Brache (H18/H19, N12-N15) ----
        E("dlg.h18.hint.1", "Die Seher tragen zwei Gläser bei sich. Nehmt sie ihnen ab — und sprecht dann mit mir.", "The seers carry two glasses. Take them from them — then talk to me."),
        E("dlg.h18.talk.merle.1", "Legt sie her. Ja — darin liegt die Wacht, von außen gesehen.", "Lay them down. Yes — inside lies the Hold, seen from outside."),
        E("dlg.h18.talk.merle.2", "Seht ihr die Gestalten um die Lichter? Das sind keine Schatten. Das sind Hüllen.", "Do you see the figures around the lights? Those aren't shadows. Those are husks."),
        E("dlg.h18.talk.merle.3", "Sie ziehen zu genau den Laternen, deren Glut sie tragen. So ruft das Glas sie heim.", "They drift to exactly the lanterns whose ember they carry. That's how the glass calls them home."),
        E("dlg.h18.talk.merle.4", "Und auf Tamms Scherbe steht sein Name. Er hat es gewusst — und ist trotzdem gefahren.", "And Tamm's shard bears his name. He knew — and drove anyway."),
        E("dlg.h19.hint.1", "Die Säulen tragen Scheiben für jeden Namen. Bringt mir drei Scherben, ich setze sie zusammen.", "The pillars carry panes for every name. Bring me three shards, I'll fit them together."),
        E("dlg.n12.offer.1", "Tamm ist nicht heimgekommen. Sein Karren steht noch in der Brache.", "Tamm never came home. His cart still stands in the barrens."),
        E("dlg.n12.offer.2", "Holt sein Speichenrad. Ich will etwas haben, das ich vergraben kann.", "Fetch his wheel. I want something I can bury."),
        E("dlg.n12.hint.1", "Das Rad liegt bei seinem Karren, zwischen den Trümmern im Süden.", "The wheel lies by his cart, among the rubble in the south."),
        E("dlg.n12.done.1", "Ja. Das ist sein Rad — die Speiche habe ich selbst geschnitzt.", "Yes. That's his wheel — I carved that spoke myself."),
        E("dlg.n12.done.2", "Ich vergrabe es mit dem Glas obendrauf. Verkauft wird hier nichts mehr.", "I'll bury it with the glass on top. Nothing gets sold here any more."),
        E("dlg.n13.offer.1", "Vier Gläser hat Merle. Das fünfte liegt tief in der Brache, wo keiner mehr hingeht.", "Merle has four glasses. The fifth lies deep in the barrens, where nobody goes any more."),
        E("dlg.n13.offer.2", "Bringt es mir, nicht ihm. Ich lese darin, wann die Hüllen kommen.", "Bring it to me, not to him. I'll read in it when the husks come."),
        E("dlg.n13.hint.1", "Sucht bei den Glassäulen im Süden, hinter dem Glasmacher.", "Search by the glass pillars in the south, past the Glasswright."),
        E("dlg.n13.done.1", "Fünf Gläser. Jetzt kann ich die Nächte lesen.", "Five glasses. Now I can read the nights."),
        E("dlg.n13.done.2", "Sagt es Ottilie — aber leise. Die Wacht schläft noch.", "Tell Ottilie — but quietly. The Hold still sleeps."),
        E("dlg.n14.offer.1", "Zwischen den Scherben liegt eine mit einem Namen. Tamms Name.", "Among the shards lies one with a name. Tamm's name."),
        E("dlg.n14.offer.2", "Bringt sie mir. Ich will wissen, ob er es gewusst hat.", "Bring it to me. I want to know whether he knew."),
        E("dlg.n14.hint.1", "Die eingeritzte Scherbe liegt bei den Säulen, wo das Glas am dichtesten liegt.", "The etched shard lies by the pillars, where the glass lies thickest."),
        E("dlg.n14.done.1", "Da steht er. Tamm. Eingeritzt, bevor das Glas kalt war.", "There he is. Tamm. Etched before the glass went cold."),
        E("dlg.n14.done.2", "Er hat es gewusst. Und ist trotzdem gefahren. Vergesst das nicht.", "He knew. And drove anyway. Don't forget that."),
        E("dlg.n15.offer.1", "Eine Seite fehlt mir noch. Eine Spendenseite, lose in der Brache verweht.", "One page is still missing. A donation page, blown loose across the barrens."),
        E("dlg.n15.offer.2", "Darauf steht ein Preis pro Laterne. Holt sie — bevor der Wind sie frisst.", "It names a price per lantern. Fetch it — before the wind eats it."),
        E("dlg.n15.hint.1", "Papier bleibt an Mauern hängen. Sucht bei der Ruine im Westen.", "Paper catches on walls. Search by the ruin in the west."),
        E("dlg.n15.done.1", "Da steht es. Ein Preis pro Laterne, sauber gerechnet.", "There it is. A price per lantern, neatly counted."),
        E("dlg.n15.done.2", "Was eine Laterne kostet, zahlt immer jemand. Merkt euch das.", "What a lantern costs, someone always pays. Remember that."),

        // ---- Akt III Finale S2: Wacht (H10, N6, N7; Bibel §Akt III) ----
        E("dlg.h10.offer.1", "Heute Nacht schläft die Wacht nicht. Morgen geht die Fuhre zum Moortor, und vorher will ich jede Stimme gehört haben — auch die, die sonst nur rechnet und schweigt.", "The Hold won't sleep tonight. Tomorrow the cart goes to the Fen Gate, and first I want to have heard every voice — even those that usually only count and stay silent."),
        E("dlg.h10.offer.2", "Sprecht mit Merle. Sie hat gesehen, was im Glas auf uns wartet, und sie sagt es nur einmal.", "Talk to Merle. She has seen what waits for us in the glass, and she'll say it only once."),
        E("dlg.h10.offer.3", "Sprecht mit Ilsabe und mit Jorin. Die eine zählt, der andere schweigt — beide wissen etwas, das ich nicht weiß.", "Talk to Ilsabe and to Jorin. One counts, the other keeps silent — both know something I don't."),
        E("dlg.h10.offer.4", "Und dann kommt wieder her. Die Scherbe halten wir gemeinsam an mein Licht. Was dann brennt, tragen wir hinaus.", "And then come back. Together we'll hold the shard to my light. Whatever burns then, we carry outside."),
        E("dlg.h10.hint.1", "Merle, Ilsabe, Jorin — und dann wieder zu mir. Die Nacht ist kurz, und das Moortor wartet nicht.", "Merle, Ilsabe, Jorin — and then back to me. The night is short, and the Fen Gate won't wait."),
        E("dlg.h10.done.1", "Ottilie nimmt die Scherbe und hält sie an ihre Laterne. Das Licht flackert im Takt eines Atems — und bleibt.", "Ottilie takes the shard and holds it to her lantern. The light flickers like breathing — and stays."),
        E("dlg.h10.done.2", "Alle vier haben gesprochen. Die Wacht hat entschieden, ohne dass wir abstimmen mussten: Wir fahren.", "All four have spoken. The Hold has decided without a vote: we drive."),
        E("dlg.h10.done.3", "Zum Moortor. Wir finden heraus, wer da steht — und was er von uns will.", "To the Fen Gate. We'll find out who stands there — and what they want from us."),
        E("dlg.h10.done.4", "Ruht euch aus. Bei Morgengrauen spannen wir an.", "Rest now. At dawn we harness up."),
        E("dlg.h10.done.5", "Die Spitzen sind schon im Tiegel. Was daraus wird, hält die Fenster zu — nicht die Kehlen auf.", "The points are in the crucible already. What they become will hold windows shut — not throats open."),
        E("dlg.h10.done.6", "Meine letzte Seite ist fort. Was ich euch angeboten habe, biete ich nie wieder an.", "My last page is gone. What I offered you, I'll never offer again."),
        E("dlg.h10.talk.ottilie.1", "So. Haltet sie fest — die Scherbe an mein Licht. Seht ihr, wie es flackert? Im Takt eines Atems.", "There. Hold it steady — the shard to my light. See how it flickers? Like breathing."),
        E("dlg.h10.talk.ottilie.2", "Es ist nicht mein Atem. Es ist jemandes, der draußen im Nebel steht und nach Hause will.", "It's not my breath. It's someone's, standing out in the fog, wanting to go home."),
        E("dlg.h10.talk.ottilie.3", "Morgen fahren wir hin und finden heraus, wer da steht. Geht jetzt zu den anderen. Ich halte so lange still.", "Tomorrow we drive there and find out who stands there. Go to the others now. I'll hold still until then."),
        E("dlg.h10.talk.merle.1", "Ihr wollt wissen, was euch am Moortor erwartet? Hüllen. Im Nebel. Alle mit dem Gesicht zu unseren Laternen.", "You want to know what waits at the Fen Gate? Husks. In the fog. All facing our lanterns."),
        E("dlg.h10.talk.merle.2", "Sie kommen nicht trotz des Lichts. Ihre Glut steckt darin — Tamm liegt jetzt mit drin, und er zieht mich noch immer heimwärts.", "They don't come despite the light. Their ember is inside it — Tamm lies in there now, and he still pulls me homeward."),
        E("dlg.h10.talk.merle.3", "Sagt Ottilie, dass ich fahre. Ich habe meinen Teil gefahren, aber diesen fahre ich noch.", "Tell Ottilie I'm driving. I've driven my share, but I'll drive this one too."),
        E("dlg.h10.talk.ilsabe.1", "Zum Moortor? Dann braucht ihr Proviant, und ich brauche — nein. Diesmal rechne ich nichts. Diesmal wünsche ich euch nur, dass ihr wiederkommt.", "To the Fen Gate? Then you need provisions, and I need — no. This time I count nothing. This time I only wish you back."),
        E("dlg.h10.talk.ilsabe.2", "Und wenn dort draußen jemand einen Preis nennt — zahlt ihn nicht. Sagt lieber, Ilsabe handelt alles, nur das nicht.", "And if someone out there names a price — don't pay it. Say instead that Ilsabe trades anything, only not that."),
        E("dlg.h10.talk.jorin.1", "Ihr fahrt zum Moortor. Gut.", "You're driving to the Fen Gate. Good."),
        E("dlg.h10.talk.jorin.2", "Kommt wieder. Wer zurückkommt, dem schmiede ich um, was er trägt — umsonst.", "Come back. Whoever returns, I'll reforge what they carry — for free."),
        E("dlg.n6.offer.1", "Die Lanzer tragen noch meine Spitzen. Alle, die übrig sind, gehören jetzt mir zurück.", "The lancers still carry my points. Every one that's left belongs back to me now."),
        E("dlg.n6.offer.2", "Bringt sie an die Schmiede. Und bleibt dann da — ich schmelze ein, und ihr seht zu.", "Bring them to the smithy. And stay — I'll melt them down, and you'll watch."),
        E("dlg.n6.hint.1", "Spitzen. Von Lanzern, die nicht mehr laufen. An die Schmiede damit.", "Points. From lancers that walk no more. To the smithy with them."),
        E("dlg.n6.done.1", "Legt sie her. Alle.", "Lay them down. All of them."),
        E("dlg.n6.done.2", "Seht zu. Was ich geschmiedet habe, mache ich ungeschehen — Stück für Stück.", "Watch. What I forged I'll undo — piece by piece."),
        E("dlg.n6.done.3", "Und das nächste Umschmieden geht auf mich. Einmal. Für die Fahrt zum Moortor.", "And the next reforge is on me. Once. For the drive to the Fen Gate."),
        E("dlg.n7.offer.1", "Eine Seite fehlt mir noch. Die letzte Spendenseite — lose, irgendwo zwischen hier und den Mauern verweht.", "One page is still missing. The last donation page — loose, blown somewhere between here and the walls."),
        E("dlg.n7.offer.2", "Bringt sie mir. Zweihundert Gold. Und dann hört mir einmal zu, statt nur zu zählen, was ich zähle.", "Bring it to me. Two hundred gold. And then listen to me for once, instead of only counting what I count."),
        E("dlg.n7.hint.1", "Die letzte Seite. Papier bleibt an Mauern hängen — sucht bei den Zäunen und Mauern der Wacht.", "The last page. Paper catches on walls — search by the fences and walls of the Hold."),
        E("dlg.n7.done.1", "Da steht es. Mein letztes Angebot — schwarz auf weiß, von meiner eigenen Hand.", "There it is. My last offer — in black and white, in my own hand."),
        E("dlg.n7.done.2", "Ich biete mich an. Gegen Glas. Die Wacht braucht Licht, und ich habe nichts mehr zu geben als mich.", "I offer myself. For glass. The Hold needs light, and I have nothing left to give but me."),
        E("dlg.n7.done.3", "Nein? Gut. Dann bleibt die Seite bei mir, und das Gold geht an euch. Zweihundert. Vergesst nicht, dass ihr abgelehnt habt.", "No? Good. Then the page stays with me, and the gold goes to you. Two hundred. Don't forget that you refused."),

        // ---- N1 Ilsabes Lieferbuch ----
        E("dlg.n1.offer.1", "Ihr geht ins Moor? Dann tut mir einen Gefallen. Gegen Bezahlung, natürlich.", "Going into the fen? Then do me a favour. Paid, of course."),
        E("dlg.n1.offer.2", "Bei der alten Kiste liegt mein Moorvorrat, in Wachstuch gewickelt. Darin ein Lieferbuch. Nichts Wertvolles. Nur Zahlen.", "By the old chest lies my fen cache, wrapped in oilcloth. A ledger inside. Nothing valuable. Just numbers."),
        E("dlg.n1.offer.3", "Bringt es mir ungelesen. Hundertfünfzig Gold. Für Ungelesenes zahle ich gut.", "Bring it to me unread. A hundred and fifty gold. I pay well for unread."),
        E("dlg.n1.hint.1", "Das Lieferbuch. Wachstuch, bei der Kiste. Ungelesen, sagte ich.", "The ledger. Oilcloth, by the chest. Unread, I said."),
        E("dlg.n1.done.1", "Danke. Das Wachstuch ist aufgeschnitten. Na ja.", "Thank you. The oilcloth has been cut open. Oh well."),
        E("dlg.n1.done.2", "Ihr habt die Spalte mit den Mengen gesehen und gedacht: So viele Tote gibt es im ganzen Moor nicht. Stimmt. Merkt euch, dass ihr das gedacht habt.", "You saw the column of amounts and thought: there aren't that many dead in the whole fen. True. Remember that you thought it."),
        E("dlg.n1.done.3", "Hundertfünfzig. Gezählt.", "A hundred and fifty. Counted."),

        // ---- N2 Die stillen Brüder ----
        E("dlg.n2.offer.1", "An den Sarkophagen im Beinhaus hängen Grabtafeln. Die Brüder schreiben ihren Namen darauf, bevor sie sterben, nicht danach.", "Grave tablets hang on the sarcophagi in the ossuary. The brothers write their names on them before they die, not after."),
        E("dlg.n2.offer.2", "Lest mir drei davon. Ich will wissen, wer dort unten noch steht.", "Read me three of them. I want to know who is still standing down there."),
        E("dlg.n2.hint.1", "Die Tafeln hängen an den Sarkophagen. Drei reichen. Es gibt mehr.", "The tablets hang on the sarcophagi. Three will do. There are more."),
        E("dlg.n2.done.1", "Bruder Benno. Bruder Kaspar. Bruder Thewes. Thewes hat mir das Lesen beigebracht.", "Brother Benno. Brother Kaspar. Brother Thewes. Thewes taught me to read."),
        E("dlg.n2.done.2", "Darunter steht etwas, in ihrer eigenen Hand: ‚Meine Gebeine dem Grund, solange der Grund sie braucht.‘", "Below it, in their own hand: ‘My bones to the ground, as long as the ground needs them.’"),
        E("dlg.n2.done.3", "Er hat sie nicht gezwungen. Sie haben sich ihm angeboten. Nehmt das. Thewes hätte gewollt, dass es jemand trägt, der noch geht.", "He didn't force them. They offered themselves to him. Take this. Thewes would have wanted it worn by someone who still walks."),

        // ---- N3 Hagedorns Spitzen ----
        E("dlg.n3.offer.1", "Der Ofen ist offen, hab ich gehört.", "The kiln is open, I hear."),
        E("dlg.n3.offer.2", "Die Aschenlanzer tragen meine Spitzen. Jede hab ich gehärtet. Bringt mir sechs zurück. Ich will sie einschmelzen, bevor sie noch wen finden.", "The ash lancers carry my points. I hardened every one. Bring me six back. I want them melted down before they find anyone else."),
        E("dlg.n3.hint.1", "Sechs Spitzen. Die Lanzer stürmen in gerader Linie. Geht zur Seite.", "Six points. The lancers charge in a straight line. Step aside."),
        E("dlg.n3.done.1", "Sechs.", "Six."),
        E("dlg.n3.done.2", "Gegen Plünderer, hab ich gesagt. Das war gelogen. Die waren gegen Knechte, die weglaufen wollten. Die Widerhaken sollten nicht töten. Nur festhalten.", "Against looters, I said. That was a lie. They were for thralls who tried to run. The barbs weren't meant to kill. Only to hold."),
        E("dlg.n3.done.3", "Nehmt das Material. Das nächste Umschmieden zahle ich. Mehr hab ich nicht.", "Take the material. I'll pay for the next reforge. That's all I have."),

        // ---- N4 Tamm ----
        E("dlg.n4.offer.1", "Tamm trägt eine Karrnermarke. Blech, mit einer Drei drauf. Er war der dritte Fahrer.", "Tamm wears a carter's tag. Tin, with a three on it. He was the third driver."),
        E("dlg.n4.offer.2", "Er ist jetzt einer von denen, die das Glas vorn tragen und die anderen anführen.", "He's one of those now who wear the glass in front and lead the others."),
        E("dlg.n4.offer.3", "Ich will ihn nicht zurück. Ich will, dass er aufhört. Bringt mir die Marke.", "I don't want him back. I want him to stop. Bring me the tag."),
        E("dlg.n4.hint.1", "Ein Glasvogt. Die Marke hängt ihm am Hals, wenn noch ein Hals da ist.", "A glass reeve. The tag hangs at his neck, if there's still a neck."),
        E("dlg.n4.done.1", "Merle nimmt die Marke, wischt den Staub mit dem Daumen ab und legt sie in den Sack zu dem Glutglas.", "Merle takes the tag, wipes the dust off with her thumb and puts it in the sack with the emberglass."),
        E("dlg.n4.done.2", "Da drin ist er nicht allein.", "He isn't alone in there."),
        E("dlg.n4.done.3", "Nehmt das Gold. Für die Rückfahrt brauche ich es nicht mehr.", "Take the gold. I won't need it for the drive back."),

        // ---- N5 Was die Seher sahen ----
        E("dlg.n5.offer.1", "Merle erzählt, die Seher in der Brache schauen in Gläser und sehen, was kommt.", "Merle says the augurs in the barrens look into glasses and see what's coming."),
        E("dlg.n5.offer.2", "Ich hätte gern zwei davon. Merle muss das nicht wissen. Wer weiß, wann die Hüllen kommen, weiß, wann die nächste Abgabe fällig ist.", "I'd like two of them. Merle needn't know. Whoever knows when the husks come knows when the next levy is due."),
        E("dlg.n5.offer.3", "Schaut nicht so. Irgendwer muss vorausdenken. Vier Seher sollten reichen, damit zwei Gläser heil bleiben.", "Don't look at me like that. Someone has to think ahead. Four augurs should leave two glasses whole."),
        E("dlg.n5.hint.1", "Vier Seher. Zwei heile Gläser. Ich habe etwas Schönes für euch zurückgelegt.", "Four augurs. Two whole glasses. I've put something nice aside for you."),
        E("dlg.n5.done.1", "Wunderbar. Seht ihr? Drei Hüllen im Nebel, links vom Moortor. Morgen vier.", "Wonderful. You see? Three husks in the fog, left of the Fen Gate. Four tomorrow."),
        E("dlg.n5.done.2", "Nehmt den Reif. Er hat einem Seher gehört, der zu viel gesehen hat. Ich habe ihn günstig bekommen.", "Take the circlet. It belonged to an augur who saw too much. I got it cheap."),

        // ---- Akt I Vertiefung S2: Moor/Beinhaus (R1 zweiter Karren, R2 siebte Tafel) ----
        E("dlg.h14.offer.1", "Noch ein Karren steckt im Moor. Jünger als der erste, und sein Siegelband fehlt.", "One more cart is stuck in the fen. Newer than the first, and its seal ribbon is missing."),
        E("dlg.h14.offer.2", "Zwei Fetzen hängen noch am Holz. Bringt sie mir, beide.", "Two scraps still hang on the wood. Bring them to me, both."),
        E("dlg.h14.offer.3", "Derselbe Moorschläger? Nein. Ein anderer. Sie vermehren sich wie Rechnungen.", "The same fen brute? No. Another one. They multiply like bills."),
        E("dlg.h14.offer.4", "Und schaut nach einem Band. Jeder Karren trägt eines. Wenn es fehlt, fehlt es nicht von allein.", "And look for a ribbon. Every cart carries one. When it's missing, it's not missing by itself."),
        E("dlg.h14.hint.1", "Die Fetzen am zweiten Karren, im Moor bei der alten Kiste. Der Moorschläger bewacht sie noch.", "The scraps on the second cart, in the fen by the old chest. The fen brute still guards them."),
        E("dlg.h14.done.1", "Zeigt her. Zwei Fetzen.", "Show me. Two scraps."),
        E("dlg.h14.done.2", "‚… fuhr nicht für die …' Der Rest fehlt. Ohne das Band liest sich der Satz nicht zu Ende.", "'… did not drive for the …' The rest is missing. Without the ribbon the sentence won't read whole."),
        E("dlg.h14.done.3", "Mit dem Band des Vogts liest er sich: ‚Der zweite Karren fuhr nicht für die Toten.' Jüngere Schrift. Sein Karren.", "With the reeve's ribbon it reads: 'The second cart did not drive for the dead.' Newer writing. His cart."),
        E("dlg.h15.offer.1", "Sechs Tafeln hängen an den Sarkophagen. Die siebte liegt in Stücken auf dem Boden.", "Six tablets hang on the sarcophagi. The seventh lies in pieces on the floor."),
        E("dlg.h15.offer.2", "Drei Bruchstücke. Sammelt sie auf, alle drei.", "Three fragments. Pick them up, all three."),
        E("dlg.h15.offer.3", "Thewes hat darunter gelegen. Fragt mich nicht, woher ich das weiß. Bringt sie mir, und ich sage es euch.", "Thewes lay beneath it. Don't ask how I know. Bring them to me, and I'll tell you."),
        E("dlg.h15.hint.1", "Die Bruchstücke im Beinhaus, bei den Sarkophagen. Drei. Thewes' Stück liegt am weitesten unten.", "The fragments in the ossuary, by the sarcophagi. Three. Thewes' piece lies lowest."),
        E("dlg.h15.talk.ottilie.1", "Legt sie zusammen. Vorsichtig. Die Kanten sind schärfer, als sie aussehen.", "Lay them together. Carefully. The edges are sharper than they look."),
        E("dlg.h15.talk.ottilie.2", "‚Schuld: … Personen, Ausgleich in …' Der Rest bleibt blind. Kein Todestag, keine Namen.", "'Debt: … persons, settled in …' The rest stays blind. No date of death, no names."),
        E("dlg.h15.talk.ottilie.3", "Thewes' Grablicht brennt noch an seinem Sarkophag. Holt es. Bei seinem Licht lesen wir den Rest.", "Thewes' grave light still burns on his sarcophagus. Fetch it. By its light we'll read the rest."),
        E("dlg.n8.offer.1", "Am zweiten Karren hing ein Siegelband. Jetzt hängt es nicht mehr. Sucht es.", "A seal ribbon hung on the second cart. Now it doesn't. Find it."),
        E("dlg.n8.offer.2", "Hundert Gold, wenn es das Siegel trägt, das ich fürchte.", "A hundred gold, if it bears the seal I fear."),
        E("dlg.n8.hint.1", "Das Band am zweiten Karren, im Moor. Rot wie Vogtswachs.", "The ribbon on the second cart, in the fen. Red like reeve's wax."),
        E("dlg.n8.done.1", "Das Siegel des Vogts. Sauber gedrückt.", "The reeve's seal. Cleanly pressed."),
        E("dlg.n8.done.2", "Hundert, wie versprochen. Und sagt niemandem, dass ihr es mir gezeigt habt.", "A hundred, as promised. And tell no one you showed it to me."),
        E("dlg.n9.offer.1", "Thewes hat sein Grablicht nie gelöscht. Es brennt noch, an seinem Sarkophag.", "Thewes never put out his grave light. It still burns, on his sarcophagus."),
        E("dlg.n9.offer.2", "Bringt es mir. Sechzig Gold. Ich will es selbst auspusten.", "Bring it to me. Sixty gold. I want to blow it out myself."),
        E("dlg.n9.hint.1", "Thewes' Sarkophag, im Beinhaus. Das Licht erkennt ihr am Geruch nach Wachs.", "Thewes' sarcophagus, in the ossuary. You'll know the light by the smell of wax."),
        E("dlg.n9.done.1", "Noch warm. Er hat es nie gelöscht, der Dickkopf.", "Still warm. He never put it out, the stubborn man."),
        E("dlg.n9.done.2", "Bei seinem Licht liest sich die siebte Tafel zu Ende: ‚Schuld: zwei Personen, Ausgleich in Glas.'", "By its light the seventh tablet reads whole: 'Debt: two persons, settled in glass.'"),
        E("dlg.n9.done.3", "Sechzig. Und jetzt lösche ich es doch nicht. Es soll brennen, bis ich weiß, wer die zwei waren.", "Sixty. And now I won't put it out after all. It shall burn until I know who the two were."),

        // ---- Akt I Vertiefung S3: Ofen/Wacht (R3 Siegel-Entscheidung, H5-Finale) ----
        E("dlg.h16.offer.1", "Im Ofen liegt ein Buch, das ich nie lesen wollte. Die Fuhrliste der Meisterin.", "There is a book in the kiln I never wanted to read. The master's cart manifest."),
        E("dlg.h16.offer.2", "Sie hat alles aufgeschrieben. Jeden Namen, jede Fuhre. Auch meine.", "She wrote down everything. Every name, every cartload. Mine too."),
        E("dlg.h16.offer.3", "Ich habe ihr die Lieferungen gefahren, bevor ich geschmiedet habe. Holt die Liste. Ich will wissen, was ich gefahren habe.", "I drove her deliveries before I forged. Fetch the list. I want to know what I drove."),
        E("dlg.h16.offer.4", "Zwei Lanzer bewachen das Buch. Nehmt ihnen die Spitzen ab, wenn ihr schon dabei seid.", "Two lancers guard the book. Take their points off them while you're at it."),
        E("dlg.h16.hint.1", "Die Liste liegt im Ofen. Die Lanzer davor tragen noch meine Spitzen.", "The list lies in the kiln. The lancers before it still carry my points."),
        E("dlg.h16.done.1", "Zeigt her. Ja. Das ist meine Hand, neben ihrer.", "Show me. Yes. That's my hand, next to hers."),
        E("dlg.h16.done.2", "Vierzehn Fuhren im Winter. Kranke, Alte. Ich habe gefragt, sie hat gerechnet. Ich bin weiter gefahren.", "Fourteen cartloads in winter. Sick, old. I asked, she counted. I kept driving."),
        E("dlg.h16.done.3", "Die Spitzen schmelze ich ein. Alle. Was ich geschmiedet habe, mache ich ungeschehen, St\u00fcck f\u00fcr St\u00fcck.", "I'll melt the points down. All of them. What I forged I'll undo, piece by piece."),
        E("dlg.h16.done.4", "Sagt Ottilie, sie soll die Namen laut lesen. Alle. Auch meinen.", "Tell Ottilie to read the names aloud. All of them. Mine too."),
        E("dlg.h17.offer.1", "Zwei H\u00e4nde haben das Buch geschrieben. Die Meisterin hat gebrannt, Ilsabe hat gerechnet.", "Two hands wrote the book. The master burned, Ilsabe counted."),
        E("dlg.h17.offer.2", "Geht zu ihr. Lasst euch das Siegel erkl\u00e4ren. Das des Vogts, auf jeder Seite.", "Go to her. Have her explain the seal. The reeve's, on every page."),
        E("dlg.h17.offer.3", "Und dann kommt zu mir. Ich muss wissen, wem ich glaube, bevor ich die Laterne l\u00f6sche.", "And then come to me. I need to know whom I believe before I put out the lantern."),
        E("dlg.h17.talk.ilsabe.1", "Das Siegel? Der Vogt siegelt alles, was die Wacht hergibt. Tote, Lebende, Papier.", "The seal? The reeve seals everything the Hold gives up. Dead, living, paper."),
        E("dlg.h17.talk.ilsabe.2", "Ich habe angeboten, was niemand vermisst. Das war der Handel. Ist es noch.", "I offered what nobody missed. That was the trade. Still is."),
        E("dlg.h17.talk.ilsabe.3", "Und hier mein letztes Angebot: Vergesst die Seite. Sagt Ottilie, das Siegel sei echt und die Sache vorbei.", "And here's my last offer: forget the page. Tell Ottilie the seal is genuine and the matter closed."),
        E("dlg.h17.talk.ilsabe.4", "Nein? Dann geht zu ihr. Sagt ihr, was ihr wollt. Ich bin immer noch da, wenn das Licht ausgeht.", "No? Then go to her. Tell her what you like. I'll still be here when the light goes out."),
        E("dlg.h17.talk.ottilie.1", "Sie hat euch ein Angebot gemacht. Ich sehe es euch an. Sie macht immer Angebote.", "She made you an offer. I can see it on you. She always makes offers."),
        E("dlg.h17.talk.ottilie.2", "Das Siegel ist echt. Die Hand ist ihre. Zwei Wahrheiten, eine Schuld.", "The seal is genuine. The hand is hers. Two truths, one guilt."),
        E("dlg.h17.talk.ottilie.3", "Ich glaube dem Buch. Nicht ihr, nicht ihm. Dem Buch.", "I believe the book. Not her, not him. The book."),
        E("dlg.h17.talk.ottilie.4", "Geht jetzt. Was ich heute Abend tue, will ich allein tun.", "Go now. What I do tonight, I want to do alone."),
        E("dlg.n10.offer.1", "Die Knechte im Ofen. Habt ihr gesehen, wie sie gl\u00fchen?", "The thralls in the kiln. Did you see them glow?"),
        E("dlg.n10.offer.2", "Das sind keine W\u00e4chter. Das sind Knechte, die tragen wollten und nicht durften. Erl\u00f6st vier von ihnen.", "Those aren't wardens. They're thralls who wanted to carry and weren't allowed. Release four of them."),
        E("dlg.n10.hint.1", "Vier Knechte im Ofen. Sie platzen, wenn sie fallen. Bleibt nicht stehen.", "Four thralls in the kiln. They burst when they fall. Don't stand still."),
        E("dlg.n10.done.1", "Vier. Habt ihr gesehen, was sie in den H\u00e4nden hatten?", "Four. Did you see what they held in their hands?"),
        E("dlg.n10.done.2", "Glut. Keine Waffe. Sie wollten tragen, nicht bewachen. Achtzig Gold. Und vergesst nicht, was ihr gesehen habt.", "Embers. No weapon. They wanted to carry, not guard. Eighty gold. And don't forget what you saw."),
        E("dlg.n11.offer.1", "Ihr geht in den Ofen? Dann sucht mir eine Seite. Eine lose, ru\u00dfgeschw\u00e4rzt, aus ihrem Buch.", "Going into the kiln? Then find me a page. A loose one, black with soot, from her book."),
        E("dlg.n11.offer.2", "Darauf steht ein Preis. Pro Name. Ich will wissen, was ich wert war. Die Preise habe schlie\u00dflich ich gemacht.", "It names a price. Per name. I want to know what I was worth. I set the prices, after all."),
        E("dlg.n11.offer.3", "Hundertzwanzig Gold, wenn sie echt ist. Ihre Hand erkenne ich.", "A hundred and twenty gold, if it's genuine. I'll know her hand."),
        E("dlg.n11.hint.1", "Eine lose Ru\u00dfseite, im Ofen. Sie riecht nach Fett und Zorn.", "A loose soot page, in the kiln. It smells of grease and anger."),
        E("dlg.n11.done.1", "Zeigt her. Ja. Das ist ihre Hand. Und meine Zahl darunter.", "Show me. That's her hand. And my figure below it."),
        E("dlg.n11.done.2", "Vier Gold pro Name im Winter, sechs im Fr\u00fchjahr. Die Teuerung, versteht ihr. Hundertzwanzig, wie versprochen.", "Four gold per name in winter, six in spring. Inflation, you see. A hundred and twenty, as promised."),
        E("dlg.h5.offer.7", "Auf der Ru\u00dfseite steht ein Preis pro Name. Ilsabe hat ihn selbst darunter geschrieben. Geht zu ihr, bevor ich tue, was ich tun muss.", "The soot page names a price per name. Ilsabe wrote it below herself. Go to her, before I do what I must."),
        E("dlg.h4.done.5", "Die Knechte, sagt ihr, trugen noch Glut in den H\u00e4nden. Die Wacht hat sie geschickt, nicht der Ofen. Ich schreibe ihre Namen zu den anderen.", "The thralls, you say, still carried embers in their hands. The Hold sent them, not the kiln. I'll write their names with the others."),
        E("dlg.h5.done.5", "Den Preis kennt ihr jetzt. Sagt es ihnen morgen, wenn sie fragen, was eine Laterne kostet.", "You know the price now. Tell them tomorrow, when they ask what a lantern costs."),
        E("dlg.h5.done.6", "Fragt mich nicht, was eine Laterne kostet. Ich habe aufgeh\u00f6rt zu z\u00e4hlen.", "Don't ask me what a lantern costs. I've stopped counting."),
        E("bark.lancer.fall", "Noch eine Spitze f\u00fcr Jorins Schmelze.", "One more point for Jorin's melt."),
        // Akt II Vertiefung S2: Brache (R4/R5-Funde).
        E("bark.sehglas.find", "Zwei Gläser. Darin liegt die Wacht, von außen gesehen.", "Two glasses. Inside lies the Hold, seen from outside."),
        E("bark.scherben.find", "Drei Scherben. Sie passen aneinander — eine Scheibe, ein Name.", "Three shards. They fit together — one pane, one name."),
        E("bark.thrall.fall", "Leer. Sie trugen nichts als Glut in den H\u00e4nden.", "Empty. They carried nothing but embers in their hands."),

        // ---- Barks (cinderreach-story-voice): Bosse im Kampf, Erzähler an Wendepunkten ----
        E("bark.abbot.phase2", "Bruder Benno. Bruder Kaspar. Bruder Thewes. Steht auf. Die Liste ist noch nicht zu Ende.", "Brother Benno. Brother Kaspar. Brother Thewes. Stand up. The list isn't finished."),
        E("bark.abbot.death", "Lest die Namen. Lest sie laut.", "Read the names. Read them aloud."),
        E("bark.kilnmother.phase2", "Zwölf Körbe Asche für eine Laterne im Monat. Rechnet nach. Ich habe es jeden Tag getan.", "Twelve baskets of ash for one lantern a month. Do the sums. I did them every day."),
        E("bark.kilnmother.death", "Ich habe niemanden geholt. Sie wurden mir gebracht. Von euch.", "I fetched no one. They were brought to me. By you."),
        E("bark.glasswright.phase2", "Wendeline, hab keine Angst. Sie wollen dich nur ansehen. Ich halte dich.", "Wendeline, don't be afraid. They only want to look at you. I'm holding you."),
        E("bark.glasswright.death", "Ihr nennt es Gefangenschaft. Ich nenne es: nicht loslassen.", "You call it captivity. I call it: not letting go."),
        E("bark.h4.start", "Hinter dem Tor ist die Luft so heiß, dass der Ruß nicht fällt. Irgendwo zählt eine Stimme Körbe.", "Past the gate the air is so hot the soot doesn't fall. Somewhere a voice is counting baskets."),
        E("bark.h7.done", "Im letzten Sehglas liegt die Laternenwacht, von außen gesehen. Um ihre Lichter steht der Nebel voller Gestalten, alle mit dem Gesicht zur Tür.", "In the last seeing glass lies Lantern Hold, seen from outside. Around its lights the fog is full of figures, all facing the door."),

        // ---- Idle ----
        E("dlg.idle.ottilie.1.1", "Ich zähle die Laternen, bevor es dunkel wird. Danach zählt sie keiner mehr.", "I count the lanterns before dark. After that nobody counts them."),
        E("dlg.idle.ottilie.2.1", "Sechsundvierzig. Fragt mich morgen wieder.", "Forty-six. Ask me again tomorrow."),
        E("dlg.idle.ottilie.3.1", "Ich habe heute keine gelöscht. Ich habe nur lange hingesehen.", "I put none out today. I only looked for a long time."),
        E("dlg.idle.merle.1.1", "Die Brache ist still, seit er tot ist. Still ist nicht dasselbe wie gut.", "The barrens have been quiet since he died. Quiet isn't the same as good."),
    };
}
